def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_ws() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while True:
            skip_ws()
            if pos < n and (expr[pos] == '+' or expr[pos] == '-'):
                op = expr[pos]
                pos += 1
                rhs = parse_term()
                if op == '+':
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_ws()
            if pos < n and expr[pos] in ('*', '/', '%'):
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == '*':
                    val *= rhs
                elif op == '/':
                    if rhs == 0:
                        raise ZeroDivisionError
                    q = abs(val) // abs(rhs)
                    val = -q if (val < 0) != (rhs < 0) else q
                else:
                    if rhs == 0:
                        raise ZeroDivisionError
                    r = abs(val) % abs(rhs)
                    val = -r if val < 0 else r
            else:
                break
        return val

    def parse_unary() -> int:
        nonlocal pos
        neg = False
        while True:
            skip_ws()
            if pos < n and expr[pos] == '-':
                neg = not neg
                pos += 1
            else:
                break
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        nonlocal pos
        items = [(False, parse_atom())]
        while True:
            skip_ws()
            if pos < n and expr[pos] == '^':
                pos += 1
                neg = False
                while True:
                    skip_ws()
                    if pos < n and expr[pos] == '-':
                        neg = not neg
                        pos += 1
                    else:
                        break
                items.append((neg, parse_atom()))
            else:
                break
        res = items[-1][1]
        if items[-1][0]:
            res = -res
        for i in range(len(items) - 2, -1, -1):
            if res < 0:
                raise ZeroDivisionError
            res = items[i][1] ** res
            if items[i][0]:
                res = -res
        return res

    def parse_atom() -> int:
        nonlocal pos
        skip_ws()
        if expr[pos] == '(':
            pos += 1
            val = parse_expr()
            skip_ws()
            pos += 1
            return val
        start = pos
        while pos < n and '0' <= expr[pos] <= '9':
            pos += 1
        return int(expr[start:pos])

    try:
        return parse_expr()
    except ZeroDivisionError:
        return "error"
